import { PaymentErrorCodeEnum, TransactionStatusEnum } from '../enums';

export class FatoorahInvoiceTransactionModelDto {
  /**
   * The date of the transaction related to the invoice.
   * Format: ISO 8601 (e.g., "2025-01-22T10:30:00Z").
   */
  TransactionDate: string;

  /**
   * The gateway the transaction was processed through.
   */
  PaymentGateway: string;

  /**
   * The reference that is generated by the payment gateway.
   */
  ReferenceId: string;

  /**
   * The track number used to track the transaction with the gateway.
   */
  TrackId: string;

  /**
   * The transaction ID.
   */
  TransactionId: string;

  /**
   * The payment ID assigned to this transaction.
   */
  PaymentId: string;

  /**
   * The authorization ID assigned to this transaction.
   */
  AuthorizationId: string;

  /**
   * The status of the transaction.

   */
  TransactionStatus: TransactionStatusEnum;

  /**
   * The value of the transaction.
   */
  TransactionValue: string;

  /**
   * The service charges considered on the customer during the transaction.
   */
  CustomerServiceCharge: string;

  /**
   * The total service charge deducted from MyFatoorah.
   */
  TotalServiceCharge: string;

  /**
   * The amount value of this transaction.
   */
  DueValue: string;

  /**
   * The currency used to pay the transaction.
   */
  PaidCurrency: string;

  /**
   * The currency value used to pay the transaction.
   */
  PaidCurrencyValue: string;

  /**
   * The value of the VAT amount for the transaction.
   */
  VatAmount: number;

  /**
   * The transaction currency.
   */
  Currency: string;

  /**
   * The error message associated with the transaction, if any.
   * This error is from the acquirer bank/platform.
   */
  Error?: string;

  ErrorCode: PaymentErrorCodeEnum;
}
